1	/**
2	 * @module features/tv-dashboard/model/types
3	 *
4	 * Tipos de domínio do Dashboard de Crise (painel TV `/tv`).
5	 * Spec: `.harness/spec/dashboard-tv-crise/spec.md`.
6	 */
7	
8	/**
9	 * Canal de origem do dado de venda de uma unidade.
10	 *
11	 * - `degust-live`: lojas integradas ao POS Degust (flash-vendas ao vivo).
12	 *   O conjunto de lojas vem da tabela `degust_stores` em runtime (hoje:
13	 *   Lago Sul, Águas Claras, BSB Shopping) — nunca hardcoded.
14	 * - `linx-lagged`: lojas no POS Linx sem integração live — usamos o último
15	 *   dia disponível em `historico_vendas` com selo "até DD/MM".
16	 * - `factory`: fábrica (sem venda; card de produção/expedição).
17	 */
18	export type TvSalesChannel = 'degust-live' | 'linx-lagged' | 'factory';
19	
20	/** Estado RAG (red/amber/green) de um card de unidade. */
21	export type TvRagStatus = 'ok' | 'amber' | 'red';
22	
23	/**
24	 * Filtro global de período do painel (v3): hoje / semana corrente
25	 * (segunda→hoje) / mês corrente (dia 1º→hoje). Perdas, compras e seus
26	 * comparativos respeitam o filtro; vendas dos cards são SEMPRE de hoje.
27	 */
28	export type TvPeriod = 'today' | 'week' | 'month';
29	
30	/** Range de dias FECHADO [from, to], ambos YYYY-MM-DD no fuso local. */
31	export interface TvDateRange {
32	  from: string;
33	  to: string;
34	}
35	
36	/** Severidade de um item de estoque crítico (zerado pesa mais). */
37	export type TvCriticalSeverity = 'zerado' | 'abaixo-minimo';
38	
39	/**
40	 * Item de estoque crítico NOMEADO de uma unidade, já ordenável por
41	 * severidade (zerados ⛔ primeiro; depois ⚠ por % faltante).
42	 */
43	export interface TvCriticalItem {
44	  nome: string;
45	  quantidade: number;
46	  minima: number;
47	  severity: TvCriticalSeverity;
48	}
49	
50	/** Linha do feed de movimentações nomeado ("AGORA" / drill-down). */
51	export interface TvRecentMove {
52	  /** Hora local HH:mm derivada de `data_movimentacao` ("—" se ausente). */
53	  hora: string;
54	  /** Timestamp cru ISO da movimentação (ordenar/tooltip), ou null. */
55	  timestamp: string | null;
56	  /** Tipo cru (`entrada` | `saida` | outros valores da tabela). */
57	  tipo: string;
58	  produtoNome: string;
59	  quantidade: number;
60	}
61	
62	/** Perdas agregadas (tabela `perdas`) no período do filtro global. */
63	export interface TvPerdasSummary {
64	  /** R$ somado de `valor_estimado` (linhas sem valor contam como 0). */
65	  valor: number;
66	  /** Número de registros de perda no período. */
67	  itens: number;
68	  /** Delta % vs período anterior equivalente (null sem base positiva). */
69	  deltaPct: number | null;
70	}
71	
72	/** Compras (NFs) agregadas — usado no drill-down por loja. */
73	export interface TvComprasSummary {
74	  valor: number;
75	  deltaPct: number | null;
76	}
77	
78	/** Marketing (ações de `acoes_marketing`) agregado no período do filtro global. */
79	export interface TvMarketingSummary {
80	  /** R$ somado de `valor_estimado` das ações de marketing. */
81	  valor: number;
82	  /** Número de ações de marketing no período. */
83	  acoes: number;
84	  /** Delta % vs período anterior equivalente (null sem base positiva). */
85	  deltaPct: number | null;
86	}
87	
88	/** Linha detalhada de perda (drill-down por loja). */
89	export interface TvPerdaDetail {
90	  id: number;
91	  produtoNome: string;
92	  quantidade: number;
93	  unidade: string | null;
94	  motivo: string;
95	  /** R$ estimado da perda (0 quando não informado). */
96	  valor: number;
97	  /** Timestamp ISO de `data_identificacao`, ou null. */
98	  data: string | null;
99	}
100	
101	/** Linha detalhada de NF de compra (drill-down por loja). */
102	export interface TvNotaFiscalDetail {
103	  id: number;
104	  numero: string;
105	  fornecedor: string;
106	  valor: number;
107	  /** Data de emissão `data_nota` (YYYY-MM-DD — campo canônico no app). */
108	  dataNota: string;
109	}
110	
111	/**
112	 * Quebra delivery×balcão de uma loja num dia (R1 da spec
113	 * `tv-acompanhamento-live`). Hoje só faz sentido para o BSB Shopping
114	 * (única loja cujo delivery entra junto no PDV — ver
115	 * `TV_DELIVERY_SPLIT_LOJA_ID` em tvMath).
116	 */
117	export interface TvDeliverySplit {
118	  lojaId: number;
119	  /** Dia a que a quebra se refere (YYYY-MM-DD). */
120	  data: string;
121	  /** R$ líquido somado dos cupons tipoVenda='2' (delivery) não cancelados. */
122	  totalDelivery: number;
123	  /** Número de cupons de delivery no dia. */
124	  cuponsDelivery: number;
125	}
126	
127	/**
128	 * Curva horária de vendas de uma loja num dia (movimentacao-produtos).
129	 * Usada como FRAÇÃO (cumulativo até a hora ÷ total) aplicada ao total
130	 * oficial — nunca como valor absoluto (kits têm valorUnitario 0).
131	 */
132	export interface TvHourlyCurve {
133	  lojaId: number;
134	  /** Dia da curva (YYYY-MM-DD). */
135	  data: string;
136	  /** R$ aproximado por hora cheia, chave "HH" com duas casas ("10".."22"). */
137	  byHour: Record<string, number>;
138	}
139	
140	/** Linha de `metas_mensais` normalizada (loja_id NULL = meta da rede). */
141	export interface TvMetaMensal {
142	  lojaId: number | null;
143	  ano: number;
144	  /** Mês 1-12 (convenção da tabela, NÃO o monthIndex0 do JS). */
145	  mes: number;
146	  valorMeta: number;
147	}
148	
149	/** Segmento seg-dom recortado ao mês (primeiro/último podem ter menos de 7 dias). */
150	export interface TvWeekSegment {
151	  /** 1-based ("Semana 1" do mês). */
152	  index: number;
153	  /** Primeiro dia do segmento (YYYY-MM-DD local). */
154	  from: string;
155	  /** Último dia do segmento (YYYY-MM-DD local). */
156	  to: string;
157	  /** Quantidade de dias do segmento (1-7). */
158	  days: number;
159	}
160	
161	/** Meta semanal recalculada de um segmento do mês (R4 da spec). */
162	export interface TvWeeklyGoal {
163	  segment: TvWeekSegment;
164	  /**
165	   * Meta da semana: redistribuição iterativa da meta mensal — semana que
166	   * não bate aumenta as seguintes; semana que supera reduz. Invariante:
167	   * realizado das semanas passadas + targets restantes = meta mensal.
168	   */
169	  target: number;
170	  /** Realizado no segmento (null para semanas futuras sem dados). */
171	  achieved: number | null;
172	  /** true quando o segmento contém o dia de hoje. */
173	  isCurrent: boolean;
174	}
175	
176	/** Acompanhamento do mês corrente (R3+R4): MTD, meta mensal e semanas. */
177	export interface TvMonthProgress {
178	  /** Faturamento acumulado da rede no mês (01 → hoje, lojas Degust). */
179	  mtdTotal: number;
180	  /** Meta mensal da rede (linha loja_id NULL; fallback soma por loja). */
181	  metaMensal: number | null;
182	  /** % da meta mensal já realizada (null sem meta cadastrada). */
183	  pctMeta: number | null;
184	  /** Projeção de fim de mês por run-rate (mtd ÷ dias decorridos × dias do mês). */
185	  projection: number;
186	  /** Semanas do mês com metas redistribuídas (vazio sem meta cadastrada). */
187	  weeks: TvWeeklyGoal[];
188	  /** Semana corrente (null sem meta cadastrada ou fora do mês). */
189	  currentWeek: TvWeeklyGoal | null;
190	  /** MTD por loja (lojas Degust) — usado no relatório matinal. */
191	  mtdByLoja: Map<number, number>;
192	}
193	
194	/** Nível de frescor de um dado-fonte em relação ao intervalo esperado. */
195	export type TvFreshnessLevel = 'fresh' | 'stale' | 'very-stale';
196	
197	/** Severidade de uma exceção exibida na faixa inferior. */
198	export type TvExceptionSeverity = 'red' | 'amber';
199	
200	/** Tipo de exceção exibida na faixa inferior. */
201	export type TvExceptionKind =
202	  | 'stock-out'
203	  | 'stock-low'
204	  | 'no-movement'
205	  | 'stale-data';
206	
207	/** Janela de funcionamento usada no pró-rata da meta (hora local 0-24). */
208	export interface TvBusinessHours {
209	  start: number;
210	  end: number;
211	}
212	
213	/** Snapshot de vendas de uma unidade (live ou defasado). */
214	export interface TvSalesSnapshot {
215	  /** Valor vendido em R$ no dia de referência. */
216	  valor: number;
217	  /** Número de cupons/transações (null quando a fonte não informa). */
218	  cupons: number | null;
219	  /** Ticket médio em R$ (null quando a fonte não informa). */
220	  ticketMedio: number | null;
221	  /** Dia a que o dado se refere (YYYY-MM-DD). Para canal live = hoje. */
222	  dataReferencia: string;
223	  /** true quando o dado é ao vivo (flash-vendas); false = defasado. */
224	  isLive: boolean;
225	  /** Caixa aberto agora (apenas canal live; null quando não se aplica). */
226	  caixaAberto: boolean | null;
227	  /** Timestamp informado pela fonte da última atualização (ISO, ou null). */
228	  atualizadoEm: string | null;
229	}
230	
231	/** Contadores de alerta de estoque de uma unidade (apenas produtos ativos). */
232	export interface TvStockAlertSummary {
233	  /** Itens com quantidade ≤ 0 e mínimo definido (positivo). */
234	  zerados: number;
235	  /** Itens com quantidade entre 0 exclusivo e o mínimo. */
236	  abaixoMinimo: number;
237	}
238	
239	/** Item de estoque em alerta (detalhe usado na faixa de exceções). */
240	export interface TvStockAlertItem {
241	  produtoNome: string;
242	  quantidade: number;
243	  quantidadeMinima: number;
244	  /** true = zerado (vermelho); false = abaixo do mínimo (âmbar). */
245	  zerado: boolean;
246	}
247	
248	/** Heartbeat de movimentações de estoque de uma unidade no dia. */
249	export interface TvMovementSummary {
250	  /** Contagem de movimentações tipo `entrada` hoje. */
251	  entradas: number;
252	  /** Contagem de movimentações tipo `saida` hoje. */
253	  saidas: number;
254	  /** Timestamp ISO da última movimentação ("última bipagem"), ou null. */
255	  ultimaBipagem: string | null;
256	}
257	
258	/** Dados de um card de loja no grid. */
259	export interface TvStoreData {
260	  lojaId: number;
261	  nome: string;
262	  channel: TvSalesChannel;
263	  /** Vendas do dia de referência (null quando não há dado disponível). */
264	  vendas: TvSalesSnapshot | null;
265	  /** Meta do dia da semana de referência (`metas_vendas`), ou null. */
266	  metaDia: number | null;
267	  /**
268	   * % da meta. Canal live = pró-rata da janela de funcionamento;
269	   * canal defasado = % do dia COMPLETO de referência (dia já encerrado).
270	   * null quando não há meta cadastrada ou fora da janela.
271	   */
272	  pctMeta: number | null;
273	  /**
274	   * Delta % vs MESMO DIA da semana anterior — comparativo SECUNDÁRIO desde
275	   * a v3 (o principal é {@link deltaOntem}); a UI decide o que mostrar.
276	   */
277	  deltaSemana: number | null;
278	  /**
279	   * Delta % vs DIA ANTERIOR — comparativo PRINCIPAL (v3).
280	   * Canal live: hoje vs ontem com base PRÓ-RATEADA no mesmo ponto do dia.
281	   * Canal defasado: último dia vs dia anterior a ele (dias completos).
282	   */
283	  deltaOntem: number | null;
284	  estoque: TvStockAlertSummary;
285	  movimentacao: TvMovementSummary;
286	  /** Perdas da loja no PERÍODO do filtro global (+ delta vs anterior). */
287	  perdas: TvPerdasSummary;
288	  /** Marketing (ações `acoes_marketing`) da loja no PERÍODO (+ delta). */
289	  marketing: TvMarketingSummary;
290	  /**
291	   * Estoque crítico NOMEADO, ordenado por severidade (zerados primeiro,
292	   * depois abaixo do mínimo por % faltante). Lista completa — a coluna
293	   * exibe o top 5; o drill-down, tudo.
294	   */
295	  criticalItems: TvCriticalItem[];
296	  /** Mini-feed "AGORA": últimas movimentações de hoje (mais recente 1º). */
297	  recentMoves: TvRecentMove[];
298	  rag: TvRagStatus;
299	  /** Motivos legíveis (pt-BR) que levaram ao estado RAG. */
300	  ragReasons: string[];
301	  /**
302	   * Quebra "Loja R$X · Delivery R$Y" do dia exibido — preenchida SOMENTE
303	   * para a loja `TV_DELIVERY_SPLIT_LOJA_ID` (BSB Shopping) no período
304	   * `today` (live ou dia passado). `balcao` = total oficial − delivery,
305	   * clampado em ≥ 0. null/ausente nas demais lojas e períodos.
306	   */
307	  deliverySplit?: { delivery: number; balcao: number } | null;
308	}
309	
310	/** Produção agregada da fábrica num dia. */
311	export interface TvFactoryProduction {
312	  /** Dia a que a produção se refere (YYYY-MM-DD — último dia com registro). */
313	  dataReferencia: string;
314	  /** Quantidade de produtos distintos produzidos. */
315	  itens: number;
316	  /** Soma das quantidades produzidas. */
317	  totalUnidades: number;
318	}
319	
320	/** Dados do card diferenciado da fábrica. */
321	export interface TvFactoryData {
322	  lojaId: number;
323	  nome: string;
324	  /** Produção do dia (`daily_production` com loja_id NULL), ou null. */
325	  producao: TvFactoryProduction | null;
326	  /** Expedições = movimentações da fábrica hoje (saídas para lojas). */
327	  expedicoes: TvMovementSummary;
328	  estoque: TvStockAlertSummary;
329	  /** Perdas da fábrica no PERÍODO do filtro global (+ delta). */
330	  perdas: TvPerdasSummary;
331	  /** Marketing (ações `acoes_marketing` da fábrica) no PERÍODO (+ delta). */
332	  marketing: TvMarketingSummary;
333	  /** Estoque crítico nomeado da fábrica (mesma ordenação das lojas). */
334	  criticalItems: TvCriticalItem[];
335	  /** Mini-feed "AGORA" da fábrica (últimas movimentações de hoje). */
336	  recentMoves: TvRecentMove[];
337	  rag: TvRagStatus;
338	  ragReasons: string[];
339	}
340	
341	/** Uma linha da faixa de exceções. */
342	export interface TvException {
343	  /** Id estável para keys de render (ex.: `stock-out:4:BROWNIE`). */
344	  id: string;
345	  kind: TvExceptionKind;
346	  severity: TvExceptionSeverity;
347	  lojaId: number | null;
348	  lojaNome: string | null;
349	  /** Mensagem pronta para exibição (pt-BR). */
350	  message: string;
351	  produtoNome?: string;
352	  quantidade?: number;
353	  quantidadeMinima?: number;
354	}
355	
356	/** Faixa de exceções já ordenada (vermelho antes de âmbar) e limitada. */
357	export interface TvExceptionsResult {
358	  items: TvException[];
359	  /** Quantas exceções ficaram de fora do limite (para "+N itens"). */
360	  overflowCount: number;
361	  /** Total de exceções antes do corte. */
362	  totalCount: number;
363	}
364	
365	/** Resumo da rede para o hero. */
366	export interface TvNetworkSummary {
367	  /**
368	   * Vendas de HOJE em R$ — soma apenas das lojas cujo dado é de hoje
369	   * (canal live). Lojas defasadas NÃO entram para não misturar dias.
370	   */
371	  vendasHoje: number;
372	  /** Soma das metas do dia das lojas que contribuem em `vendasHoje`. */
373	  metaDia: number | null;
374	  /** % da meta pró-rata da rede (mesma regra do card de loja live). */
375	  pctMetaProRata: number | null;
376	  /**
377	   * Delta % vs mesmo dia da semana passada (lojas live) — SECUNDÁRIO
378	   * desde a v3 ({@link deltaOntem} é o principal), ou null.
379	   */
380	  deltaSemana: number | null;
381	  /**
382	   * Delta % vs ONTEM (lojas live, base pró-rateada no mesmo ponto do
383	   * dia) — comparativo PRINCIPAL da v3, ou null.
384	   */
385	  deltaOntem: number | null;
386	  /**
387	   * Perdas da REDE no período do filtro (toda a tabela `perdas`,
388	   * inclusive linhas sem loja_id — que não aparecem em nenhuma coluna).
