77	  const data = useTvDashboardData(period);
78	  useTvRealtime();
79	  const now = useMinuteClock();
80	
81	  const rankedStores = useMemo(() => {
82	    if (!data.stores) return [] as typeof data.stores;
83	    return data.stores.map((s, _, arr) => {
84	      const vendas = s.vendas?.valor ?? 0;
85	      const rank =
86	        vendas > 0 ? arr.filter((x) => (x.vendas?.valor ?? 0) > vendas).length + 1 : null;
87	      return { ...s, rank };
88	    });
89	  }, [data.stores]);
