106	  const storeCards = rankedStores.slice(0, data.factory ? 5 : 6);
107	
108	  return (
109	    <MommaPageLayout>
110	
111	      <div
112	        className="flex flex-col gap-4 p-4 sm:p-6 font-momma text-[#2D362E]"
113	        data-testid="tv-dashboard"
114	      >
115	        {/* Botão voltar mobile */}
116	        <div className="flex items-center lg:hidden">
117	          <button
118	            type="button"
119	            onClick={() => navigate(-1)}
120	            className="flex items-center gap-1.5 rounded-full border border-[#57715B]/20 bg-white/70 px-3 py-1.5 text-sm font-medium text-[#57715B] backdrop-blur-sm transition-colors hover:bg-[#57715B]/10"
121	            aria-label="Voltar"
122	          >
123	            <ArrowLeft className="h-4 w-4" aria-hidden />
124	            Voltar
125	          </button>
126	        </div>
127	
128	        {/* Hero: vendas da rede, marketing, perdas, filtro período */}
129	        <TvHero
130	          network={data.network}
131	          freshness={data.freshness}
132	          now={now}
133	          period={period}
134	          onPeriodChange={setPeriod}
135	          onMetasClick={() => navigate('/tv/metas')}
136	        />
137	
138	        {/* Grid de colunas — responsivo, sem scroll horizontal */}
139	        <div>
140	          <div className="grid gap-4 grid-cols-2 sm:grid-cols-3 lg:grid-cols-6">
141	            {data.isError ? (
142	              Array.from({ length: 6 }, (_, i) => <TvErrorCard key={i} />)
143	            ) : (
144	              <>
145	                {storeCards.map((store, idx) => (
146	                  <div
147	                    key={store.lojaId}
148	                    className={`flex min-w-0 flex-col ${COL_ENTER_CLS[idx] ?? 'tv-col-enter tv-col-enter-1'}`}
149	                  >
150	                    <TvStoreColumn
151	                      store={store}
152	                      liveLevel={data.freshness.vendasLive.level}
153	                      period={period}
154	                      now={now}
155	                      rank={store.rank}
156	                    />
157	                  </div>
158	                ))}
159	                {data.factory && (
160	                  <div
161	                    className={`flex min-w-0 flex-col ${COL_ENTER_CLS[storeCards.length] ?? 'tv-col-enter tv-col-enter-6'}`}
162	                  >
163	                    <TvFabricaColumn
164	                      factory={data.factory}
165	                      freshness={data.freshness}
166	                      period={period}
167	                      now={now}
168	                    />
169	                  </div>
170	                )}
171	              </>
172	            )}
173	          </div>
174	        </div>
175	      </div>
176	    </MommaPageLayout>
177	  );
178	}
