273	                · {network.perdas.itens} {network.perdas.itens === 1 ? 'item' : 'itens'}
274	              </span>
275	            )}
276	          </p>
277	          <p className="mt-1">
278	            <TvHeroDeltaLine deltaPct={network?.perdas.deltaPct ?? null} amberWhenUp />
279	          </p>
280	        </div>
281	
282	      </div>
283	    </header>
284	  );
285	}
