657	/** Entrada de {@link buildNoMovementException}. */
658	export interface NoMovementExceptionInput {
659	  lojaId: number;
660	  lojaNome: string;
661	  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
662	  lastMovementAt: Date | string | null;
663	  now: Date;
664	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
665	  hours?: TvBusinessHours;
666	  /** Threshold em horas (default lojas 3h; fábrica 2h). */
667	  thresholdHours?: number;
668	}
