727	// ─────────────────────────────────────────────────────────────────────────────
728	// Staleness
729	// ─────────────────────────────────────────────────────────────────────────────
730	
731	/**
732	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
733	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
734	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
735	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
736	 */
737	export function classifyStaleness(
738	  lastUpdatedAt: Date | string | number | null | undefined,
739	  expectedIntervalMs: number,
740	  now: Date,
741	): TvFreshnessLevel {
742	  if (lastUpdatedAt == null) return 'very-stale';
743	  const ts = new Date(lastUpdatedAt).getTime();
744	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
745	  const age = now.getTime() - ts;
746	  if (age < 2 * expectedIntervalMs) return 'fresh';
747	  if (age < 6 * expectedIntervalMs) return 'stale';
748	  return 'very-stale';
749	}
750	
751	/**
752	 * Monta o freshness consolidado a partir dos timestamps CRUS de última
753	 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
754	 *
755	 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
756	 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
757	 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
758	 * parar de avançar além de 2× o intervalo esperado.
759	 */
760	export function buildFreshness(
761	  liveUpdatedAtMs: number,
762	  stockUpdatedAtMs: number,
763	  intervals: { liveMs: number; slowMs: number },
764	  now: Date,
765	): TvFreshness {
766	  const liveUpdatedAt =
767	    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
768	  const stockUpdatedAt =
769	    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
770	  return {
771	    vendasLive: {
772	      updatedAt: liveUpdatedAt,
773	      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
774	      expectedIntervalMs: intervals.liveMs,
775	    },
776	    estoque: {
777	      updatedAt: stockUpdatedAt,
778	      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
779	      expectedIntervalMs: intervals.slowMs,
780	    },
781	    geradoEm: now.toISOString(),
782	  };
783	}
