785	// ─────────────────────────────────────────────────────────────────────────────
786	// Exceções — ordenação e corte
787	// ─────────────────────────────────────────────────────────────────────────────
788	
789	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
790	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
791	const KIND_ORDER: Record<string, number> = {
792	  'stock-out': 0,
793	  'stock-low': 1,
794	  'no-movement': 2,
795	  'stale-data': 3,
796	};
797	
798	/**
799	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
800	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
801	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
802	 * contagem do excedente.
803	 */
804	export function sortAndLimitExceptions(
805	  exceptions: TvException[],
806	  limit: number = TV_EXCEPTIONS_LIMIT,
807	): TvExceptionsResult {
808	  const sorted = [...exceptions].sort((a, b) => {
809	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
810	    if (sev !== 0) return sev;
811	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
812	    if (kind !== 0) return kind;
813	    return a.message.localeCompare(b.message, 'pt-BR');
814	  });
815	  return {
816	    items: sorted.slice(0, limit),
817	    overflowCount: Math.max(0, sorted.length - limit),
818	    totalCount: sorted.length,
819	  };
820	}
