985	/**
986	 * Corrige o `loja_id` das linhas de flash-vendas.
987	 *
988	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
989	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
990	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
991	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
992	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
993	 *
994	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
995	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
996	 * - Caso contrário → descarta (não corromper outra loja).
997	 */
998	export function remapFlashLojaIds(
999	  rows: FlashRow[],
1000	  degustCodeToLoja: ReadonlyMap<number, number>,
1001	  knownDegustLojaIds: ReadonlySet<number>,
1002	): FlashRow[] {
1003	  const out: FlashRow[] = [];
1004	  for (const row of rows) {
1005	    if (knownDegustLojaIds.has(row.loja_id)) {
1006	      out.push(row);
1007	      continue;
1008	    }
1009	    const mapped = degustCodeToLoja.get(row.loja_id);
1010	    if (mapped != null) {
1011	      out.push({ ...row, loja_id: mapped });
1012	    }
1013	    // não mapeável → descartado de propósito (ver TSDoc)
1014	  }
1015	  return out;
1016	}
1017	
1018	/**
1019	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
1020	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
1021	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
1022	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
1023	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
1024	 * o drill-down, a lista completa.
1025	 */
1026	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
1027	  const missingFraction = (c: TvCriticalItem): number =>
1028	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
1029	  return items
1030	    .map<TvCriticalItem>((i) => ({
1031	      nome: i.produtoNome,
1032	      quantidade: i.quantidade,
1033	      minima: i.quantidadeMinima,
1034	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
1035	    }))
1036	    .sort((a, b) => {
1037	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
1038	      const diff = missingFraction(b) - missingFraction(a);
1039	      if (diff !== 0) return diff;
1040	      return a.nome.localeCompare(b.nome, 'pt-BR');
1041	    });
1042	}
1043	
1044	/** Linha mínima de `perdas` necessária à agregação por loja/rede. */
1045	export interface PerdaAggRow {
1046	  loja_id: number | null;
1047	  valor_estimado: number | null;
1048	}
1049	
1050	/** Perdas agregadas (R$ + nº de registros). */
1051	export interface PerdasAggregate {
1052	  valor: number;
1053	  itens: number;
1054	}
1055	
1056	/** Resultado da agregação de perdas: por loja + total da rede. */
1057	export interface PerdasByLoja {
1058	  byLoja: Map<number, PerdasAggregate>;
1059	  /** Total da REDE — inclui linhas sem loja_id (fora de qualquer coluna). */
1060	  total: PerdasAggregate;
1061	}
1062	
1063	/**
1064	 * Agrega perdas do período: R$ (soma de `valor_estimado`, nulls contam 0 —
1065	 * a perda EXISTE mesmo sem valor estimado e entra na contagem de itens) e
1066	 * nº de registros, por loja e total da rede. Linhas sem loja_id entram
1067	 * SOMENTE no total (não há coluna para atribuí-las).
1068	 */
1069	export function aggregatePerdas(rows: PerdaAggRow[]): PerdasByLoja {
1070	  const byLoja = new Map<number, PerdasAggregate>();
1071	  const total: PerdasAggregate = { valor: 0, itens: 0 };
1072	  for (const row of rows) {
1073	    const valor = row.valor_estimado ?? 0;
1074	    total.valor += valor;
1075	    total.itens += 1;
1076	    if (row.loja_id == null) continue;
1077	    let agg = byLoja.get(row.loja_id);
1078	    if (!agg) {
1079	      agg = { valor: 0, itens: 0 };
1080	      byLoja.set(row.loja_id, agg);
1081	    }
1082	    agg.valor += valor;
1083	    agg.itens += 1;
1084	  }
1085	  return { byLoja, total };
1086	}
