1118	    let agg = byLoja.get(row.loja_id);
1119	    if (!agg) {
1120	      agg = { valor: 0, acoes: 0 };
1121	      byLoja.set(row.loja_id, agg);
1122	    }
1123	    agg.valor += valor;
1124	    agg.acoes += 1;
1125	  }
1126	  return { byLoja, total };
