1128	
1129	/** Linha do feed de movimentações (nome do produto já resolvido no fetch). */
1130	export interface MovementFeedRow {
1131	  loja_id: number | null;
1132	  tipo_movimentacao: string;
1133	  data_movimentacao: string | null;
1134	  quantidade: number | null;
1135	  produtoNome: string;
1136	}
1137	
1138	/** Converte uma linha crua do feed em {@link TvRecentMove} exibível. */
1139	export function mapFeedRow(row: MovementFeedRow): TvRecentMove {
1140	  return {
1141	    hora: timeHHMMFromIso(row.data_movimentacao),
1142	    timestamp: row.data_movimentacao,
1143	    tipo: row.tipo_movimentacao,
1144	    produtoNome: row.produtoNome,
1145	    quantidade: row.quantidade ?? 0,
1146	  };
1147	}
1148	
1149	/**
1150	 * Agrupa o feed (já ordenado DESC por `data_movimentacao` na query) por
1151	 * loja, mantendo as `perStore` primeiras linhas de cada uma (mini-feed
1152	 * "AGORA"). Linhas sem loja são ignoradas. NÃO reordena — confia na
1153	 * ordenação da query (única fonte do "mais recente primeiro").
1154	 */
1155	export function buildRecentMoves(
1156	  rows: MovementFeedRow[],
1157	  perStore: number = TV_MINI_FEED_SIZE,
1158	): Map<number, TvRecentMove[]> {
1159	  const out = new Map<number, TvRecentMove[]>();
1160	  for (const row of rows) {
1161	    if (row.loja_id == null) continue;
1162	    let list = out.get(row.loja_id);
1163	    if (!list) {
1164	      list = [];
1165	      out.set(row.loja_id, list);
1166	    }
1167	    if (list.length >= perStore) continue;
1168	    list.push(mapFeedRow(row));
1169	  }
1170	  return out;
1171	}
1172	
1173	// ─────────────────────────────────────────────────────────────────────────────
1174	// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
1175	// ─────────────────────────────────────────────────────────────────────────────
1176	
1177	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
1178	export interface TvPageResult<T> {
1179	  data: T[] | null;
1180	  error: { message: string } | null;
1181	}
1182	
1183	/**
1184	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
1185	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
1186	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
1187	 *
1188	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
1189	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
1190	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
1191	 * sobreporem entre requests.
1192	 */
1193	export async function fetchAllPages<T>(
1194	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
1195	  pageSize = 1000,
1196	): Promise<T[]> {
1197	  const all: T[] = [];
1198	  let offset = 0;
1199	  for (;;) {
1200	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
1201	    if (error) throw error;
1202	    const rows = data ?? [];
1203	    all.push(...rows);
1204	    if (rows.length < pageSize) return all;
1205	    offset += pageSize;
1206	  }
1207	}
