1	/**
2	 * @module features/tv-dashboard/ui/TvStoreColumn
3	 *
4	 * Coluna vertical de loja — redesign baseado em research de TV dashboards
5	 * (Bach et al. IEEE TVCG 2023 + practitioner evidence):
6	 * - Número de vendas é o sinal primário → domina o espaço visualmente
7	 * - Máximo 5 elementos por card para não causar cognitive overload
8	 * - 1 RAG status por card (não 15 células coloridas)
9	 * - Detalhe de perdas/marketing/estoque → drill-down /tv/loja/:id
10	 */
11	
12	import { useEffect, useRef, useState } from 'react';
13	import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
14	import { formatCompactBRL, parseBrDateTime, parseIsoDateLocal } from '../model/tvMath';
15	import { TvDeltaChip, TvLiveIndicator, TvRankChip, TvStateChip } from './TvChips';
16	import {
17	  TvColumnBipLine,
18	  TvColumnMetaBar,
19	  TvColumnStockLine,
20	  TvUnitColumn,
21	} from './TvColumnParts';
22	import { formatTicketBRL, formatWeekdayDayMonth } from './tvFormat';
23	import { useCountUp } from './useCountUp';
24	
25	interface TvStoreColumnProps {
26	  store: TvStoreData;
27	  liveLevel: TvFreshnessLevel;
28	  period: TvPeriod;
29	  now: Date;
30	  rank?: number | null;
31	}
32	
33	/** Coluna de loja — canal Degust live ou Linx defasado. */
34	export function TvStoreColumn({ store, liveLevel, period, now, rank }: TvStoreColumnProps) {
35	  const { vendas, channel } = store;
36	  const isLive = channel === 'degust-live';
37	  const valorAnim = useCountUp(vendas?.valor ?? 0);
38	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
39	
40	  // Flash dourado ao atualizar o valor de venda
41	  const prevValueRef = useRef(vendas?.valor);
42	  const [flashing, setFlashing] = useState(false);
43	  const flashKeyRef = useRef(0);
44	  useEffect(() => {
45	    if (
46	      vendas?.valor != null &&
47	      prevValueRef.current != null &&
48	      vendas.valor !== prevValueRef.current
49	    ) {
50	      flashKeyRef.current += 1;
51	      setFlashing(true);
52	      const t = window.setTimeout(() => setFlashing(false), 450);
53	      prevValueRef.current = vendas.valor;
54	      return () => window.clearTimeout(t);
55	    }
56	    prevValueRef.current = vendas?.valor;
57	  }, [vendas?.valor]);
58	
59	  // Linha de status: fonte + horário de atualização
60	  const updateTime = isLive ? parseBrDateTime(vendas?.atualizadoEm) : null;
61	  const laggedLabel = !isLive && refDate ? formatWeekdayDayMonth(refDate) : null;
62	
63	  const showRank = rank != null && rank >= 1 && rank <= 3;
64	
65	  return (
66	    <TvUnitColumn lojaId={store.lojaId} nome={store.nome} rag={store.rag} testId="tv-store-column">
67	
68	      {/* Header: nome + chips de status */}
69	      <div className="flex items-start justify-between gap-2">
70	        <h2 className="min-w-0 font-momma text-sm font-semibold leading-tight text-[#5F6F63] truncate">
71	          {store.nome.replace(/^Momma\s+/i, '')}
72	        </h2>
73	        <div className="flex shrink-0 items-center gap-1">
74	          {showRank && <TvRankChip rank={rank as 1 | 2 | 3} />}
75	          <TvStateChip rag={store.rag} />
76	        </div>
77	      </div>
78	
79	      {/* Número de vendas + setinhas inline — exatamente como na v2 */}
80	      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
81	        <span
82	          key={flashing ? `flash-${flashKeyRef.current}` : 'static'}
83	          className={`font-momma text-3xl font-bold leading-none tabular-nums sm:text-4xl ${
84	            vendas ? 'text-[#2D362E]' : 'text-[#9ca3af]'
85	          }${flashing ? ' tv-value-flash' : ''}`}
86	          data-testid="tv-store-sales"
87	        >
88	          {vendas ? formatCompactBRL(valorAnim) : '—'}
89	        </span>
90	        {store.deltaOntem != null && (
91	          <TvDeltaChip delta={store.deltaOntem} label={isLive ? 'ontem' : 'dia ant.'} size="card" />
92	        )}
93	        {store.deltaSemana != null && period === 'week' && (
94	          <TvDeltaChip delta={store.deltaSemana} label="sem. ant." size="card" />
95	        )}
96	      </div>
97	
98	      {/* Status de fonte — compacto, sem "ao vivo" como texto */}
99	      <p className="mt-1 flex items-center gap-1.5 text-xs text-[#9ca3af]">
100	        <TvLiveIndicator channel={channel} liveLevel={liveLevel} />
101	        {isLive
102	          ? updateTime
103	            ? `${updateTime.getHours().toString().padStart(2, '0')}:${updateTime.getMinutes().toString().padStart(2, '0')}`
104	            : 'hoje'
105	          : laggedLabel ?? 'sem dados'}
106	      </p>
107	
108	      {/* Barra de meta */}
109	      <TvColumnMetaBar pctMetaProRata={store.pctMeta} metaDia={store.metaDia} now={now} />
110	
111	      {/* Nº de vendas + R$/venda — cada parte non-breaking para não cortar */}
112	      {isLive && (vendas?.cupons != null || vendas?.ticketMedio != null) && (
113	        <div className="mt-2 flex flex-wrap items-baseline gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]">
114	          {vendas?.cupons != null && (
115	            <span className="whitespace-nowrap font-medium">
116	              {vendas.cupons} vendas
117	            </span>
118	          )}
119	          {vendas?.ticketMedio != null && vendas.ticketMedio > 0 && (
120	            <span className="whitespace-nowrap">
121	              {vendas.cupons != null && '· '}
122	              <span className="font-medium">{formatTicketBRL(vendas.ticketMedio)}</span>
123	              <span>/venda</span>
124	            </span>
125	          )}
126	        </div>
127	      )}
128	
129	      {/* Bip + Status de estoque — 1 linha para cada */}
130	      <div className="mt-auto pt-3 space-y-1">
131	        <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />
132	        <TvColumnStockLine estoque={store.estoque} />
133	      </div>
134	    </TvUnitColumn>
135	  );
136	}
