input.new_string:
/** Rótulo "ter. 03/06" para o dia de referência de canal defasado. */
export function formatWeekdayDayMonth(date: Date): string {
  const dd = String(date.getDate()).padStart(2, '0');
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  return `${WEEKDAY_ABBR[date.getDay()]} ${dd}/${mm}`;
}

/** Abreviações pt-BR dos meses (índice = `Date.getMonth()`). */
export const MONTH_ABBR = [
  'jan',
  'fev',
  'mar',
  'abr',
  'mai',
  'jun',
  'jul',
  'ago',
  'set',
  'out',
  'nov',
  'dez',
] as const;

/**
 * Rótulo do range exibido no modo histórico (chip do hero, R2):
 * - dia: "ter. 10/06";
 * - semana: "02–08/06" (mês duplicado quando a semana cruza meses);
 * - mês: "mai/2026".
 */
export function formatRangeLabel(period: TvPeriod, range: TvDateRange): string {
  const from = parseIsoDateLocal(range.from);
  const to = parseIsoDateLocal(range.to);
  if (period === 'today') return formatWeekdayDayMonth(from);
  if (period === 'week') {
    const dd = (d: Date) => String(d.getDate()).padStart(2, '0');
    const mm = (d: Date) => String(d.getMonth() + 1).padStart(2, '0');
    return from.getMonth() === to.getMonth()
      ? `${dd(from)}–${dd(to)}/${mm(to)}`
      : `${dd(from)}/${mm(from)}–${dd(to)}/${mm(to)}`;
  }
  return `${MONTH_ABBR[from.getMonth()]}/${from.getFullYear()}`;
}

input.content:
/**
 * @module features/tv-dashboard/ui/TvHero
 *
 * Hero v3 da Torre de Controle: vendas da rede HOJE + % vs ONTEM
 * (comparativo principal; barra de meta pró-rata vira secundária),
 * COMPRAS e PERDAS do período do filtro global, contador de alertas
 * críticos, relógio + freshness e o FILTRO GLOBAL Hoje/Semana/Mês
 * (segmented control glass — muda perdas/compras/comparativos).
 *
 * v4 (spec tv-acompanhamento-live):
 * - navegação ◀ ▶ no histórico (R2) + chip do range exibido + "● Ao vivo";
 * - strip do mês (R3+R4): MTD, % da meta mensal, meta da semana corrente
 *   (redistribuída) e projeção de fim de mês;
 * - botão "Relatório" (R6) abre o modal do relatório matinal.
 *
 * Linha 1: marca + (freshness · relógio · filtro). Linha 2: métricas.
 * Linha 3: strip do mês. Mobile empilha; lg+ vira faixa de zonas.
 */

import {
  ArrowDown,
  ArrowUp,
  ChevronLeft,
  ChevronRight,
  FileText,
  RefreshCw,
  Settings2,
} from 'lucide-react';
import type {
  TvDateRange,
  TvFreshness,
  TvMonthProgress,
  TvNetworkSummary,
  TvPeriod,
} from '../model/types';
import { formatCompactBRL } from '../model/tvMath';
import { TvDeltaChip, TvMetaBar } from './TvChips';
import {
  TV_PERIOD_LABEL,
  expectedPctNow,
  formatDeltaPct,
  formatRangeLabel,
  formatTimeHHMM,
  metaBarColorFromRatio,
  type TvBarColor,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvHeroProps {
  network: TvNetworkSummary | null;
  freshness: TvFreshness;
  now: Date;
  /** Período do filtro global (controlado pela página). */
  period: TvPeriod;
  onPeriodChange: (period: TvPeriod) => void;
  /** Offset de navegação no histórico (≤ 0; 0 = ao vivo) — R2. */
  offset: number;
  onOffsetChange: (offset: number) => void;
  /** Range exibido (rótulo do chip no modo histórico). */
  range: TvDateRange;
  /** Acompanhamento do mês corrente (R3+R4), ou null carregando. */
  monthProgress: TvMonthProgress | null;
  onMetasClick: () => void;
  onReportClick: () => void;
}

const PERIOD_OPTIONS: ReadonlyArray<{ value: TvPeriod; label: string }> = [
  { value: 'today', label: 'Hoje' },
  { value: 'week', label: 'Semana' },
  { value: 'month', label: 'Mês' },
];

/** Cor de texto do % da meta semanal a partir da cor semântica da barra. */
const WEEK_PCT_TEXT_CLS: Record<TvBarColor, string> = {
  sage: 'text-[#57715B]',
  amber: 'text-amber-600',
  red: 'text-red-600',
};

/** Segmented control glass do filtro global (Hoje/Semana/Mês). */
function TvPeriodFilter({
  period,
  onPeriodChange,
}: {
  period: TvPeriod;
  onPeriodChange: (period: TvPeriod) => void;
}) {
  return (
    <div
      className="inline-flex shrink-0 items-center rounded-full border border-[#57715B]/15 bg-white/60 p-1 backdrop-blur-md"
      role="group"
      aria-label="Período de perdas, compras e comparativos"
      data-testid="tv-period-filter"
    >
      {PERIOD_OPTIONS.map((opt) => {
        const active = opt.value === period;
        return (
          <button
            key={opt.value}
            type="button"
            aria-pressed={active}
            data-mia-action={`filtrar-painel-tv-periodo-${opt.value}`}
            onClick={() => onPeriodChange(opt.value)}
            className={`rounded-full px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium leading-none transition-colors motion-reduce:transition-none lg:px-4 lg:py-1.5 ${
              active
                ? 'bg-[#57715B] text-white shadow-sm'
                : 'text-[#5F6F63] hover:bg-[#57715B]/10'
            }`}
          >
            {opt.label}
          </button>
        );
      })}
    </div>
  );
}

/**
 * Linha de delta vs período anterior (compras/perdas). Neutra por padrão;
 * âmbar SÓ no desvio ruim (`amberWhenUp`: perdas subindo). Sem base → texto
 * honesto "sem base anterior".
 */
function TvHeroDeltaLine({
  deltaPct,
  amberWhenUp = false,
}: {
  deltaPct: number | null;
  amberWhenUp?: boolean;
}) {
  if (deltaPct == null) {
    return (
      <span className="font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] text-[#7C887E]">
        sem base anterior
      </span>
    );
  }
  const isAmber = amberWhenUp && deltaPct > 0;
  const Icon = deltaPct < 0 ? ArrowDown : ArrowUp;
  return (
    <span
      className={`inline-flex items-center gap-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium tabular-nums ${
        isAmber ? 'text-amber-600' : 'text-[#7C887E]'
      }`}
    >
      <Icon className="h-[1em] w-[1em] shrink-0" aria-hidden />
      {formatDeltaPct(deltaPct)} vs anterior
    </span>
  );
}

/** Strip do mês (R3+R4): MTD, meta mensal, meta da semana e projeção. */
function TvHeroMonthStrip({
  monthProgress,
  now,
}: {
  monthProgress: TvMonthProgress;
  now: Date;
}) {
  const { mtdTotal, metaMensal, pctMeta, currentWeek, projection } =
    monthProgress;

  // % do mês decorrido (tick de "esperado agora" da barra mensal)
  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  const expectedMonthPct = Math.round((now.getDate() / daysInMonth) * 100);
  const monthRatio =
    pctMeta != null && expectedMonthPct > 0 ? pctMeta / expectedMonthPct : null;
  const monthBarColor = metaBarColorFromRatio(monthRatio, now);

  // Meta da semana corrente (target redistribuído × realizado)
  const weekPct =
    currentWeek && currentWeek.target > 0
      ? ((currentWeek.achieved ?? 0) / currentWeek.target) * 100
      : null;
  const weekColor = metaBarColorFromRatio(
    weekPct != null ? weekPct / 100 : null,
    now,
  );

  const labelCls =
    'font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]';
  const valueCls =
    'mt-1 font-momma text-[clamp(1.25rem,1.8vw,3.25rem)] font-bold leading-none text-[#2D362E] tabular-nums';

  return (
    <div
      className="grid grid-cols-2 items-start gap-x-4 gap-y-4 border-t border-[#57715B]/10 pt-4 lg:grid-cols-4 lg:gap-8"
      data-testid="tv-hero-month-strip"
    >
      {/* Mês até agora (MTD da rede) */}
      <div className="min-w-0">
        <span className={labelCls}>MÊS ATÉ AGORA</span>
        <p className={valueCls} data-testid="tv-hero-mtd">
          {formatCompactBRL(mtdTotal)}
        </p>
      </div>

      {/* % da meta mensal + mini barra (oculto sem meta cadastrada) */}
      {metaMensal != null && pctMeta != null ? (
        <div className="min-w-0" data-testid="tv-hero-month-goal">
          <span className={labelCls}>META MENSAL</span>
          <p className={valueCls}>
            {Math.round(pctMeta)}%
            <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
              {' '}
              de {formatCompactBRL(metaMensal)}
            </span>
          </p>
          <div className="mt-2 max-w-[18rem]">
            <TvMetaBar
              fillPct={pctMeta}
              expectedPct={expectedMonthPct}
              color={monthBarColor}
              size="card"
            />
          </div>
        </div>
      ) : (
        <div className="min-w-0" aria-hidden />
      )}

      {/* Meta da semana corrente (redistribuída — R4) */}
      {currentWeek && (
        <div className="min-w-0" data-testid="tv-hero-week-goal">
          <span className={labelCls}>META DA SEMANA</span>
          <p className={valueCls}>
            {formatCompactBRL(currentWeek.achieved ?? 0)}
            <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
              {' '}
              / {formatCompactBRL(currentWeek.target)}
            </span>
          </p>
          {weekPct != null && (
            <p
              className={`mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-semibold tabular-nums ${WEEK_PCT_TEXT_CLS[weekColor]}`}
            >
              {Math.round(weekPct)}% da semana
            </p>
          )}
        </div>
      )}

      {/* Projeção de fim de mês (run-rate — R3) */}
      <div className="min-w-0">
        <span className={labelCls}>PROJEÇÃO DO MÊS</span>
        <p className={valueCls} data-testid="tv-hero-projection">
          {formatCompactBRL(projection)}
        </p>
      </div>
    </div>
  );
}

/** Hero da rede (v4): marca/relógio/filtro + métricas + strip do mês. */
export function TvHero({
  network,
  freshness,
  now,
  period,
  onPeriodChange,
  offset,
  onOffsetChange,
  range,
  monthProgress,
  onMetasClick,
  onReportClick,
}: TvHeroProps) {
  const vendas = useCountUp(network?.vendasHoje ?? 0);
  const hasData = network != null;
  const periodLabel = TV_PERIOD_LABEL[period];
  const isLive = offset === 0;

  // Barra de meta (SECUNDÁRIA na v3): preenchimento = % do dia COMPLETO;
  // tick dourado = esperado agora (pró-rata) — só faz sentido AO VIVO.
  const fullDayPct =
    network && network.metaDia != null && network.metaDia > 0
      ? (network.vendasHoje / network.metaDia) * 100
      : null;
  const expected = expectedPctNow(now);
  const ratio = network?.pctMetaProRata != null ? network.pctMetaProRata / 100 : null;
  const barColor = metaBarColorFromRatio(ratio, now);

  const liveFresh = freshness.vendasLive.level === 'fresh';
  const liveTime = formatTimeHHMM(freshness.vendasLive.updatedAt);

  const navBtnCls =
    'inline-flex shrink-0 items-center justify-center rounded-full border border-[#57715B]/15 bg-white/60 p-1.5 text-[#57715B] backdrop-blur-md transition-colors hover:bg-[#57715B]/10 disabled:cursor-not-allowed disabled:opacity-35 disabled:hover:bg-transparent';

  return (
    <header
      className="flex flex-col gap-4 border-b border-[#C5A065]/25 pb-4 lg:gap-5"
      data-testid="tv-hero"
    >
      {/* Linha 1 — marca + relógio/freshness/filtro global */}
      <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          <span className="font-momma text-[clamp(0.625rem,0.75vw,1rem)] font-bold uppercase tracking-[0.3em] text-[#C5A065]">
            MOMMA
          </span>
          <span className="font-momma text-[clamp(1.125rem,1.6vw,2.25rem)] font-bold tracking-tight text-[#2D362E] leading-tight">
            Painel da Momma
          </span>
        </div>
        <div className="flex flex-wrap items-center gap-x-4 gap-y-2 lg:gap-x-5">
          {isLive ? (
            /* Indicador live existente (offset 0) */
            <span className={`inline-flex items-center gap-2 rounded-full px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium ${
              liveFresh
                ? 'bg-emerald-50 text-emerald-600'
                : 'border border-amber-400/40 bg-amber-50 text-amber-600'
            }`}>
              {liveFresh
                ? <><span className="h-2 w-2 rounded-full bg-emerald-400 animate-pulse" aria-hidden />{liveTime ? `atualizado ${liveTime}` : 'ao vivo'}</>
                : <><RefreshCw className="h-[0.9em] w-[0.9em] shrink-0" aria-hidden />{liveTime ? `atrasado · ${liveTime}` : 'atrasado'}</>
              }
            </span>
          ) : (
            /* Modo histórico (R2): chip do range + botão de volta ao vivo */
            <span className="inline-flex flex-wrap items-center gap-2">
              <span
                className="inline-flex items-center rounded-full bg-[#C5A065]/10 px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-semibold tabular-nums text-[#a07c43]"
                data-testid="tv-range-chip"
              >
                {formatRangeLabel(period, range)}
              </span>
              <button
                type="button"
                onClick={() => onOffsetChange(0)}
                data-mia-action="voltar-painel-tv-ao-vivo"
                className="inline-flex items-center gap-2 rounded-full bg-emerald-50 px-3 py-1 font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-medium text-emerald-600 transition-colors hover:bg-emerald-100"
              >
                <span className="h-2 w-2 rounded-full bg-emerald-400" aria-hidden />
                Ao vivo
              </button>
            </span>
          )}
          <span className="font-momma text-[clamp(1.25rem,2vw,3.75rem)] font-light leading-none text-[#2D362E] tabular-nums">
            {formatTimeHHMM(now)}
          </span>
          {/* Filtro de período com setas ◀ ▶ + botões Metas/Relatório */}
          <div className="flex flex-col items-end gap-2">
            <div className="flex items-center gap-1.5">
              <button
                type="button"
                onClick={() => onOffsetChange(offset - 1)}
                aria-label="Período anterior"
                data-mia-action="painel-tv-periodo-anterior"
                className={navBtnCls}
              >
                <ChevronLeft className="h-4 w-4" aria-hidden />
              </button>
              <TvPeriodFilter period={period} onPeriodChange={onPeriodChange} />
              <button
                type="button"
                onClick={() => onOffsetChange(Math.min(0, offset + 1))}
                disabled={offset >= 0}
                aria-label="Período seguinte"
                data-mia-action="painel-tv-periodo-seguinte"
                className={navBtnCls}
              >
                <ChevronRight className="h-4 w-4" aria-hidden />
              </button>
            </div>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={onMetasClick}
                data-mia-action="abrir-metas-painel-tv"
                className="flex items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-4 py-1.5 text-sm font-medium text-[#57715B] shadow-sm backdrop-blur-md transition-colors hover:bg-[#57715B]/10"
              >
                <Settings2 className="h-4 w-4" aria-hidden />
                Metas
              </button>
              <button
                type="button"
                onClick={onReportClick}
                data-mia-action="abrir-relatorio-painel-tv"
                className="flex items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-4 py-1.5 text-sm font-medium text-[#57715B] shadow-sm backdrop-blur-md transition-colors hover:bg-[#57715B]/10"
              >
                <FileText className="h-4 w-4" aria-hidden />
                Relatório
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Linha 2 — métricas: vendas | marketing | perdas */}
      <div className="grid grid-cols-2 items-end gap-x-4 gap-y-4 lg:grid-cols-3 lg:gap-8">
        {/* Zona 1 — vendas da rede + % vs ontem (principal) */}
        <div className="col-span-2 min-w-0 lg:col-span-1">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            {isLive ? 'REDE · VENDAS HOJE' : `REDE · VENDAS · ${periodLabel.toUpperCase()}`}
          </span>
          <div className="mt-1 flex flex-wrap items-end gap-x-4 gap-y-2">
            <span
              className="font-momma text-[clamp(2.25rem,4vw,7.5rem)] font-bold leading-none text-[#2D362E] tabular-nums"
              data-testid="tv-hero-sales"
            >
              {hasData ? formatCompactBRL(vendas) : '—'}
            </span>
            {network?.deltaOntem != null && (
              <span className="pb-1">
                <TvDeltaChip
                  delta={network.deltaOntem}
                  label={isLive ? 'ontem' : 'anterior'}
                  size="hero"
                />
              </span>
            )}
            {network?.deltaSemana != null && period === 'week' && (
              <span className="pb-1">
                <TvDeltaChip delta={network.deltaSemana} label="sem. ant." size="hero" />
              </span>
            )}
          </div>
          {/* R$/hora · vendas/hora · ticket médio da rede */}
          <div className="mt-1.5 flex flex-wrap gap-x-3 gap-y-0.5 font-momma text-[clamp(0.75rem,0.9vw,1.5rem)] tabular-nums">
            {network?.valorPorHora != null && (
              <span className="whitespace-nowrap font-semibold text-[#5F6F63]">
                {formatCompactBRL(network.valorPorHora)}<span className="font-normal text-[#7C887E]">/h</span>
              </span>
            )}
            {network?.vendasPorHora != null && (
              <span className="whitespace-nowrap font-semibold text-[#5F6F63]">
                {Math.round(network.vendasPorHora)}<span className="font-normal text-[#7C887E]"> vendas/h</span>
              </span>
            )}
            {network?.ticketMedio != null && (
              <span className="whitespace-nowrap font-semibold text-[#5F6F63]">
                ticket médio <span className="text-[#2D362E]">{formatCompactBRL(network.ticketMedio)}</span>
              </span>
            )}
          </div>
          {/* Meta pró-rata — secundária */}
          <div className="mt-2 max-w-[36rem]">
            <TvMetaBar
              fillPct={fullDayPct}
              expectedPct={fullDayPct != null && isLive ? expected : null}
              color={barColor}
              size="card"
            />
            <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] leading-tight">
              {fullDayPct != null ? (
                <>
                  <span className="font-medium text-[#5F6F63]">
                    {Math.round(fullDayPct)}% da meta
                  </span>
                  {isLive && (
                    <span className="text-[#7C887E]"> · esperado {expected}%</span>
                  )}
                </>
              ) : (
                <span className="text-[#7C887E]">sem meta cadastrada</span>
              )}
            </p>
          </div>
        </div>

        {/* Zona 2 — marketing do período */}
        <div className="min-w-0">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            MARKETING · {periodLabel}
          </span>
          <p
            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
            data-testid="tv-hero-marketing"
          >
            {network ? formatCompactBRL(network.marketing.valor) : '—'}
          </p>
          <p className="mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] text-[#7C887E]">
            {network ? `${network.marketing.acoes} ${network.marketing.acoes === 1 ? 'ação' : 'ações'}` : '—'}
          </p>
        </div>

        {/* Zona 3 — perdas do período (R$ + itens; subir é desvio → âmbar) */}
        <div className="min-w-0">
          <span className="font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
            PERDAS · {periodLabel}
          </span>
          <p
            className="mt-1 font-momma text-[clamp(1.5rem,2.1vw,3.75rem)] font-bold leading-none text-[#2D362E] tabular-nums"
            data-testid="tv-hero-perdas"
          >
            {network ? formatCompactBRL(network.perdas.valor) : '—'}
            {network && (
              <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
                {' '}
                · {network.perdas.itens} {network.perdas.itens === 1 ? 'item' : 'itens'}
              </span>
            )}
          </p>
          <p className="mt-1">
            <TvHeroDeltaLine deltaPct={network?.perdas.deltaPct ?? null} amberWhenUp />
          </p>
        </div>

      </div>

      {/* Linha 3 — strip do mês (R3+R4): sempre o mês CORRENTE */}
      {monthProgress && <TvHeroMonthStrip monthProgress={monthProgress} now={now} />}
    </header>
  );
}

/**
 * @module features/tv-dashboard/model/useTvReport
 *
 * Dados do RELATÓRIO MATINAL (R6 da spec `tv-acompanhamento-live`):
 * uma única chamada à edge `degust-pos-financial` cobrindo o mês do
 * dia-base (01 → dia-base, com quebra delivery do BSB) + `metas_mensais`
 * do mês. Deriva: faturamento do dia-base por loja e rede, MTD por loja
 * e rede, meta mensal + %, meta/realizado da semana corrente
 * (redistribuição de `weeklyTargets`) e projeção de fim de mês.
 *
 * SEM polling: o relatório é um snapshot sob demanda (modal aberto).
 * `buildTvReportText` é pura — testável sem I/O.
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import {
  TV_DELIVERY_SPLIT_LOJA_ID,
  monthEndProjection,
  parseIsoDateLocal,
  toIsoDateLocal,
  weeklyTargets,
} from './tvMath';
import type { TvWeeklyGoal } from './types';
import { fetchTvContext, tvDashboardKeys } from './useTvDashboardData';

// ─────────────────────────────────────────────────────────────────────────────
// Tipos
// ─────────────────────────────────────────────────────────────────────────────

/** Linha por loja do relatório (dia-base + acumulado do mês). */
export interface TvReportLojaLine {
  lojaId: number;
  /** Nome curto (sem o prefixo "Momma "). */
  nome: string;
  /** R$ do dia-base (null = sem venda registrada no dia → "—"). */
  valorDia: number | null;
  /** R$ acumulado 01 → dia-base. */
  mtd: number;
}

/** Snapshot derivado do relatório matinal. */
export interface TvReportData {
  /** Dia-base (YYYY-MM-DD). */
  baseDate: string;
  /** R$ da rede no dia-base. */
  totalDia: number;
  /** R$ da rede acumulado 01 → dia-base. */
  totalMtd: number;
  /** Lojas Degust ordenadas por faturamento do dia desc (sem venda no fim). */
  lojas: TvReportLojaLine[];
  /** Quebra do BSB Shopping no dia-base (null sem cupom delivery). */
  deliverySplit: { delivery: number; balcao: number } | null;
  /** Meta mensal da rede (linha NULL; fallback soma por loja), ou null. */
  metaMensal: number | null;
  /** % da meta mensal já realizada, ou null sem meta. */
  pctMeta: number | null;
  /** Semana corrente (contendo o dia-base) com meta redistribuída, ou null. */
  currentWeek: TvWeeklyGoal | null;
  /** Projeção de fim de mês por run-rate até o dia-base. */
  projection: number;
}

/** Resposta da edge `degust-pos-financial` (campos usados no relatório). */
interface DegustReportResponse {
  daily?: Array<{
    data: string;
    loja_id: number;
    total_faturado: number;
    total_cupons: number;
  }>;
  deliverySplit?: Array<{
    data: string;
    loja_id: number;
    total_delivery: number;
    cupons_delivery: number;
  }>;
}

// ─────────────────────────────────────────────────────────────────────────────
// Fetch + derivação
// ─────────────────────────────────────────────────────────────────────────────

async function fetchTvReport(baseDateIso: string): Promise<TvReportData> {
  const base = parseIsoDateLocal(baseDateIso);
  const monthStart = toIsoDateLocal(
    new Date(base.getFullYear(), base.getMonth(), 1),
  );

  const ctx = await fetchTvContext();
  const [edgeRes, metasRes] = await Promise.all([
    supabase.functions.invoke('degust-pos-financial', {
      body: {
        startDate: monthStart,
        endDate: baseDateIso,
        includeDeliverySplit: true,
        deliveryLojaId: TV_DELIVERY_SPLIT_LOJA_ID,
      },
    }),
    supabase
      .from('metas_mensais')
      .select('loja_id, valor_meta')
      .eq('ano', base.getFullYear())
      .eq('mes', base.getMonth() + 1),
  ]);
  if (edgeRes.error) {
    throw new Error(
      `[tv-report] degust-pos-financial: ${edgeRes.error.message ?? 'falha na edge'}`,
    );
  }
  const edge = (edgeRes.data ?? {}) as DegustReportResponse;
  // Meta ausente não derruba o relatório (mesma tolerância do painel)
  const metasRows = metasRes.error ? [] : (metasRes.data ?? []);

  // Agregações: dia-base por loja, MTD por loja e por data (rede)
  const dayByLoja = new Map<number, number>();
  const mtdByLoja = new Map<number, number>();
  const redeByDate = new Map<string, number>();
  for (const d of edge.daily ?? []) {
    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
    if (d.data > baseDateIso) continue;
    const valor = d.total_faturado ?? 0;
    mtdByLoja.set(d.loja_id, (mtdByLoja.get(d.loja_id) ?? 0) + valor);
    redeByDate.set(d.data, (redeByDate.get(d.data) ?? 0) + valor);
    if (d.data === baseDateIso) {
      dayByLoja.set(d.loja_id, (dayByLoja.get(d.loja_id) ?? 0) + valor);
    }
  }
  let totalDia = 0;
  for (const v of dayByLoja.values()) totalDia += v;
  let totalMtd = 0;
  for (const v of mtdByLoja.values()) totalMtd += v;

  // Linhas por loja (Degust), ordenadas por faturamento do dia desc;
  // lojas sem venda no dia ("—") vão pro fim, ordenadas por MTD.
  const lojas: TvReportLojaLine[] = ctx.lojas
    .filter((l) => ctx.degustLojaIds.has(l.id))
    .map((l) => ({
      lojaId: l.id,
      nome: l.nome.replace(/^Momma\s+/i, ''),
      valorDia: dayByLoja.has(l.id) ? (dayByLoja.get(l.id) ?? 0) : null,
      mtd: mtdByLoja.get(l.id) ?? 0,
    }))
    .sort((a, b) => (b.valorDia ?? -1) - (a.valorDia ?? -1) || b.mtd - a.mtd);

  // Quebra delivery do BSB no dia-base (balcão = total oficial − delivery)
  const splitRow = (edge.deliverySplit ?? []).find(
    (r) => r.data === baseDateIso && r.loja_id === TV_DELIVERY_SPLIT_LOJA_ID,
  );
  const bsbDia = dayByLoja.get(TV_DELIVERY_SPLIT_LOJA_ID);
  const deliverySplit =
    splitRow != null && bsbDia != null
      ? {
          delivery: splitRow.total_delivery,
          balcao: Math.max(0, bsbDia - splitRow.total_delivery),
        }
      : null;

  // Meta mensal: linha da rede (loja_id NULL); fallback = soma por loja
  const redeRow = metasRows.find((m) => m.loja_id === null);
  const lojaRows = metasRows.filter((m) => m.loja_id !== null);
  const metaMensal =
    redeRow != null
      ? redeRow.valor_meta
      : lojaRows.length > 0
        ? lojaRows.reduce((s, m) => s + m.valor_meta, 0)
        : null;

  // Semana corrente (contendo o dia-base) com redistribuição (R4)
  const weeks =
    metaMensal != null && metaMensal > 0
      ? weeklyTargets(metaMensal, redeByDate, base)
      : [];

  return {
    baseDate: baseDateIso,
    totalDia,
    totalMtd,
    lojas,
    deliverySplit,
    metaMensal,
    pctMeta:
      metaMensal != null && metaMensal > 0 ? (totalMtd / metaMensal) * 100 : null,
    currentWeek: weeks.find((w) => w.isCurrent) ?? null,
    projection: monthEndProjection(totalMtd, base),
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Texto do relatório (pura — formato pt-BR pronto pra WhatsApp)
// ─────────────────────────────────────────────────────────────────────────────

/** R$ inteiro pt-BR ("R$ 9.999") — relatório não usa centavos. */
function brl(value: number): string {
  return `R$ ${Math.round(value).toLocaleString('pt-BR')}`;
}

/** "quarta, 10/06/2026" (weekday longo sem o sufixo "-feira"). */
function formatLongDate(date: Date): string {
  const weekday = date
    .toLocaleDateString('pt-BR', { weekday: 'long' })
    .replace('-feira', '');
  return `${weekday}, ${date.toLocaleDateString('pt-BR')}`;
}

/**
 * Monta o texto do relatório matinal (R6). `todayIso` injetável para
 * teste: define se o dia-base é "ontem" (rótulo padrão do relatório)
 * ou outro dia ("Faturamento do dia").
 */
export function buildTvReportText(
  report: TvReportData,
  todayIso: string = toIsoDateLocal(new Date()),
): string {
  const base = parseIsoDateLocal(report.baseDate);
  const yesterdayOfToday = toIsoDateLocal(
    new Date(parseIsoDateLocal(todayIso).getTime() - 86_400_000),
  );
  const isYesterday = report.baseDate === yesterdayOfToday;
  const dd = String(base.getDate()).padStart(2, '0');
  const mm = String(base.getMonth() + 1).padStart(2, '0');

  const lines: string[] = [];
  lines.push('📊 *Momma — Relatório Diário*');
  lines.push(`🗓 ${formatLongDate(base)}`);
  lines.push('');
  lines.push(
    `*Faturamento ${isYesterday ? 'de ontem' : 'do dia'}:* ${brl(report.totalDia)}`,
  );
  for (const loja of report.lojas) {
    let line = `• ${loja.nome}: ${loja.valorDia != null ? brl(loja.valorDia) : '—'}`;
    if (
      loja.lojaId === TV_DELIVERY_SPLIT_LOJA_ID &&
      report.deliverySplit != null &&
      loja.valorDia != null
    ) {
      line += ` (loja ${brl(report.deliverySplit.balcao)} · delivery ${brl(report.deliverySplit.delivery)})`;
    }
    lines.push(line);
  }
  lines.push('');
  const metaPart =
    report.pctMeta != null && report.metaMensal != null
      ? ` • ${Math.round(report.pctMeta)}% da meta de ${brl(report.metaMensal)}`
      : '';
  lines.push(`*Mês (01–${dd}/${mm}):* ${brl(report.totalMtd)}${metaPart}`);
  for (const loja of [...report.lojas].sort((a, b) => b.mtd - a.mtd)) {
    lines.push(`• ${loja.nome}: ${loja.mtd > 0 ? brl(loja.mtd) : '—'}`);
  }
  lines.push('');
  if (report.currentWeek) {
    const pct =
      report.currentWeek.target > 0
        ? Math.round(
            ((report.currentWeek.achieved ?? 0) / report.currentWeek.target) * 100,
          )
        : 0;
    lines.push(
      `*Semana atual:* ${brl(report.currentWeek.achieved ?? 0)} / meta ${brl(report.currentWeek.target)} (${pct}%)`,
    );
  }
  lines.push(`*Projeção fim do mês:* ${brl(report.projection)}`);
  return lines.join('\n');
}

// ─────────────────────────────────────────────────────────────────────────────
// Hook
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Snapshot do relatório matinal para o dia-base. UMA chamada à edge por
 * dia-base (sem polling — `staleTime` longo; refetch só por troca de data
 * ou reabertura após GC do cache).
 *
 * @param baseDateIso - Dia-base (YYYY-MM-DD), tipicamente ontem.
 * @param enabled - true apenas com o modal aberto (não busca à toa).
 */
export function useTvReport(baseDateIso: string, enabled: boolean) {
  return useQuery({
    queryKey: [...tvDashboardKeys.all, 'report', baseDateIso] as const,
    queryFn: () => fetchTvReport(baseDateIso),
    enabled,
    staleTime: 5 * 60_000,
    refetchInterval: false,
    refetchOnWindowFocus: false,
  });
}

/**
 * @module features/tv-dashboard/ui/TvReportModal
 *
 * Modal do RELATÓRIO MATINAL (R6): escolhe o dia-base (default ontem),
 * mostra o preview do texto pronto (formato WhatsApp) e oferece
 * "Copiar" (clipboard) + "WhatsApp" (wa.me). Sem polling — snapshot
 * sob demanda via `useTvReport` (habilitado só com o modal aberto).
 */

import { useState } from 'react';
import { Copy, FileText, MessageCircle } from 'lucide-react';
import { toast } from 'sonner';
import { Button } from '@/shared/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import { Input } from '@/shared/ui/input';
import { addDays, toIsoDateLocal } from '../model/tvMath';
import { buildTvReportText, useTvReport } from '../model/useTvReport';

interface TvReportModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

/** Modal do relatório diário do Painel TV (copiar/compartilhar). */
export function TvReportModal({ open, onOpenChange }: TvReportModalProps) {
  // Dia-base default/máximo = ontem (relatório matinal fala do dia fechado)
  const yesterday = toIsoDateLocal(addDays(new Date(), -1));
  const [baseDate, setBaseDate] = useState(yesterday);

  const reportQuery = useTvReport(baseDate, open);
  const text = reportQuery.data ? buildTvReportText(reportQuery.data) : null;

  const handleCopy = async () => {
    if (!text) return;
    try {
      await navigator.clipboard.writeText(text);
      toast.success('Relatório copiado');
    } catch {
      toast.error('Não foi possível copiar', {
        description: 'Selecione o texto do preview e copie manualmente.',
      });
    }
  };

  const handleWhatsApp = () => {
    if (!text) return;
    window.open(
      `https://wa.me/?text=${encodeURIComponent(text)}`,
      '_blank',
      'noopener,noreferrer',
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-w-lg border-white/40 bg-white/80 backdrop-blur-xl dark:border-white/10 dark:bg-black/60 sm:rounded-2xl"
        data-testid="tv-report-modal"
      >
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 font-momma text-[#2D362E] dark:text-[#E6DCCF]">
            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-2xl bg-[#57715B]/10">
              <FileText className="h-4 w-4 text-[#57715B] dark:text-[#8FAE94]" aria-hidden />
            </span>
            Relatório diário
          </DialogTitle>
          <DialogDescription>
            Texto pronto para enviar aos sócios — faturamento do dia, acumulado
            do mês, meta e projeção.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-3">
          <label className="flex flex-wrap items-center gap-2 text-sm font-medium text-[#5F6F63]">
            Data-base
            <Input
              type="date"
              value={baseDate}
              max={yesterday}
              onChange={(e) => {
                if (e.target.value) setBaseDate(e.target.value);
              }}
              className="w-auto rounded-xl border-[#57715B]/15 bg-white/70 tabular-nums focus-visible:ring-[#57715B]/30 dark:bg-black/20"
              aria-label="Data-base do relatório"
              data-testid="tv-report-date"
            />
          </label>

          <div className="max-h-[50vh] overflow-y-auto rounded-2xl border border-white/20 bg-white/40 p-4 shadow-sm backdrop-blur-md dark:border-white/10 dark:bg-black/20">
            {reportQuery.isLoading ? (
              <div className="space-y-2 animate-pulse" aria-label="Gerando relatório">
                <div className="h-3 w-2/3 rounded-full bg-[#57715B]/10" />
                <div className="h-3 w-1/2 rounded-full bg-[#57715B]/10" />
                <div className="h-3 w-3/4 rounded-full bg-[#57715B]/10" />
                <div className="h-3 w-2/5 rounded-full bg-[#57715B]/10" />
              </div>
            ) : reportQuery.isError ? (
              <p className="text-sm text-amber-600">
                Não foi possível gerar o relatório. Tente novamente em instantes.
              </p>
            ) : (
              <pre
                className="whitespace-pre-wrap break-words font-mono text-xs leading-relaxed text-[#2D362E] tabular-nums dark:text-[#E6DCCF]"
                data-testid="tv-report-preview"
              >
                {text}
              </pre>
            )}
          </div>
        </div>

        <DialogFooter className="gap-2 sm:gap-2">
          <Button
            type="button"
            variant="outline"
            onClick={handleCopy}
            disabled={!text}
            data-mia-action="copiar-relatorio-painel-tv"
            className="rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 dark:text-[#8FAE94]"
          >
            <Copy className="mr-2 h-4 w-4" aria-hidden />
            Copiar
          </Button>
          <Button
            type="button"
            onClick={handleWhatsApp}
            disabled={!text}
            data-mia-action="compartilhar-relatorio-whatsapp"
            className="rounded-full bg-[#57715B] text-white shadow-lg shadow-[#57715B]/20 hover:bg-[#465b49]"
          >
            <MessageCircle className="mr-2 h-4 w-4" aria-hidden />
            WhatsApp
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

