/** Linha de `metas_mensais` de um mês (loja_id NULL = meta da rede). */
interface MetaMensalRow {
  id: string;
  loja_id: number | null;
  valor_meta: number;
}

async function fetchMetasMensais(ano: number, mes: number): Promise<MetaMensalRow[]> {
  const { data, error } = await supabase
    .from('metas_mensais')
    .select('id, loja_id, valor_meta')
    .eq('ano', ano)
    .eq('mes', mes);
  if (error) throw error;
  return data ?? [];
}

/** Parse de input de meta: vazio/inválido → null; aceita vírgula decimal. */
function parseMetaInput(raw: string): number | null {
  if (raw.trim() === '') return null;
  const parsed = Number(raw.replace(',', '.'));
  if (!Number.isFinite(parsed) || parsed < 0) return null;
  return parsed;
}

const lojasQuery = useQuery({ queryKey: ['tv-metas', 'lojas'], queryFn: fetchLojasVenda });
const metasQuery = useQuery({ queryKey: ['tv-metas', 'valores'], queryFn: fetchMetas });

// ── Meta mensal (R4): mês/ano selecionável, rede + por loja ──
const [mensalAno, setMensalAno] = useState(() => new Date().getFullYear());
const [mensalMes, setMensalMes] = useState(() => new Date().getMonth() + 1);
const [showMetasPorLoja, setShowMetasPorLoja] = useState(false);
const mensaisQuery = useQuery({
  queryKey: ['tv-metas', 'mensais', mensalAno, mensalMes],
  queryFn: () => fetchMetasMensais(mensalAno, mensalMes),
});

const [redeValue, setRedeValue] = useState('');
const [lojaMensalValues, setLojaMensalValues] = useState<Record<number, string>>({});
// Re-inicializa quando o mês selecionado (re)carrega do banco
useEffect(() => {
  const rows = mensaisQuery.data;
  if (!rows) return;
  const rede = rows.find((r) => r.loja_id === null);
  setRedeValue(rede && rede.valor_meta > 0 ? String(rede.valor_meta) : '');
  const next: Record<number, string> = {};
  for (const row of rows) {
    if (row.loja_id != null && row.valor_meta > 0) {
      next[row.loja_id] = String(row.valor_meta);
    }
  }
  setLojaMensalValues(next);
}, [mensaisQuery.data]);

const saveMensalMutation = useMutation({
  mutationFn: async () => {
    const rows = mensaisQuery.data ?? [];
    // Linha da REDE (loja_id NULL): o upsert do PostgREST NÃO casa NULL
    // no onConflict — select prévio (já no cache da query) + update por
    // id quando existe; insert caso contrário.
    const redeRow = rows.find((r) => r.loja_id === null) ?? null;
    const redeParsed = parseMetaInput(redeValue);
    if (redeParsed != null) {
      if (redeRow) {
        const { error } = await supabase
          .from('metas_mensais')
          .update({ valor_meta: redeParsed })
          .eq('id', redeRow.id);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('metas_mensais').insert({
          loja_id: null,
          ano: mensalAno,
          mes: mensalMes,
          valor_meta: redeParsed,
        });
        if (error) throw error;
      }
    } else if (redeRow && redeValue.trim() === '') {
      // Campo esvaziado que TINHA meta → 0 (semanticamente sem meta)
      const { error } = await supabase
        .from('metas_mensais')
        .update({ valor_meta: 0 })
        .eq('id', redeRow.id);
      if (error) throw error;
    }

    // Por loja: loja_id não-nulo casa normal no onConflict
    const persistedLojaIds = new Set(
      rows
        .filter((r) => r.loja_id != null && r.valor_meta > 0)
        .map((r) => r.loja_id as number),
    );
    const lojaRows: Array<{
      loja_id: number;
      ano: number;
      mes: number;
      valor_meta: number;
    }> = [];
    for (const loja of lojasQuery.data ?? []) {
      const raw = lojaMensalValues[loja.id] ?? '';
      const parsed = parseMetaInput(raw);
      if (parsed != null) {
        lojaRows.push({
          loja_id: loja.id,
          ano: mensalAno,
          mes: mensalMes,
          valor_meta: parsed,
        });
      } else if (raw.trim() === '' && persistedLojaIds.has(loja.id)) {
        lojaRows.push({
          loja_id: loja.id,
          ano: mensalAno,
          mes: mensalMes,
          valor_meta: 0,
        });
      }
    }
    if (lojaRows.length > 0) {
      const { error } = await supabase
        .from('metas_mensais')
        .upsert(lojaRows, { onConflict: 'loja_id,ano,mes' });
      if (error) throw error;
    }
  },
  onSuccess: () => {
    toast.success('Meta mensal salva');
    queryClient.invalidateQueries({ queryKey: ['tv-metas', 'mensais'] });
    queryClient.invalidateQueries({ queryKey: tvDashboardKeys.metasMensais() });
  },
  onError: (error: Error) => {
    toast.error('Erro ao salvar meta mensal', {
      description: error.message || 'Tente novamente em instantes.',
    });
  },
});

// Anos selecionáveis (anterior, corrente, próximo)
const anoOptions = useMemo(() => {
  const current = new Date().getFullYear();
  return [current - 1, current, current + 1];
}, []);

