import { fireEvent, render, screen } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { TvHero } from './TvHero';
import type {
  TvFreshness,
  TvMonthProgress,
  TvNetworkSummary,
} from '../model/types';

// qui 04/06/2026, 14:30 — dentro da janela comercial
const NOW = new Date(2026, 5, 4, 14, 30);

const network: TvNetworkSummary = {
  vendasHoje: 21_300,
  metaDia: 30_000,
  pctMetaProRata: 110,
  deltaSemana: 5,
  deltaOntem: 12,
  perdas: { valor: 480, itens: 7, deltaPct: 25 },
  marketing: { valor: 5_200, acoes: 12, deltaPct: -10 },
  ticketMedio: 98.5,
  valorPorHora: 3_200,
  vendasPorHora: 32,
  totalCupons: 216,
  alertasCriticos: 2,
  lojasLive: 3,
  lojasDefasadas: 2,
};

const freshness: TvFreshness = {
  vendasLive: {
    updatedAt: new Date(2026, 5, 4, 14, 29).toISOString(),
    level: 'fresh',
    expectedIntervalMs: 60_000,
  },
  estoque: {
    updatedAt: new Date(2026, 5, 4, 14, 25).toISOString(),
    level: 'fresh',
    expectedIntervalMs: 300_000,
  },
  geradoEm: NOW.toISOString(),
};

const monthProgress: TvMonthProgress = {
  mtdTotal: 150_000,
  metaMensal: 400_000,
  pctMeta: 37.5,
  projection: 380_000,
  weeks: [],
  currentWeek: {
    segment: { index: 1, from: '2026-06-01', to: '2026-06-07', days: 7 },
    target: 90_000,
    achieved: 45_000,
    isCurrent: true,
  },
  mtdByLoja: new Map<number, number>(),
};

function renderHero(
  options: {
    period?: 'today' | 'week' | 'month';
    offset?: number;
    monthProgress?: TvMonthProgress | null;
  } = {},
) {
  const onPeriodChange = vi.fn();
  const onOffsetChange = vi.fn();
  const onReportClick = vi.fn();
  render(
    <TvHero
      network={network}
      freshness={freshness}
      now={NOW}
      period={options.period ?? 'today'}
      onPeriodChange={onPeriodChange}
      offset={options.offset ?? 0}
      onOffsetChange={onOffsetChange}
      range={{ from: '2026-06-03', to: '2026-06-03' }}
      monthProgress={options.monthProgress ?? null}
      onMetasClick={vi.fn()}
      onReportClick={onReportClick}
    />,
  );
  return { onPeriodChange, onOffsetChange, onReportClick };
}

describe('TvHero v3 — métricas da rede', () => {
  it('mostra vendas de hoje + delta principal vs ONTEM', () => {
    renderHero();
    expect(screen.getByTestId('tv-hero-sales')).toHaveTextContent('R$ 21,3k');
    // hero tem 2 chips: deltaOntem (primeiro) + deltaSemana
    expect(screen.getAllByTestId('tv-delta-chip')[0]).toHaveTextContent('12% vs ontem');
  });

  it('mostra marketing e perdas do período com rótulo do filtro', () => {
    renderHero();
    expect(screen.getByText('MARKETING · hoje')).toBeInTheDocument();
    expect(screen.getByTestId('tv-hero-marketing')).toHaveTextContent('R$ 5,2k');
    expect(screen.getByText('PERDAS · hoje')).toBeInTheDocument();
    expect(screen.getByTestId('tv-hero-perdas')).toHaveTextContent('R$ 480');
    expect(screen.getByTestId('tv-hero-perdas')).toHaveTextContent('7 itens');
  });

  it('rótulo das métricas acompanha o período selecionado', () => {
    renderHero({ period: 'month' });
    expect(screen.getByText('MARKETING · mês')).toBeInTheDocument();
    expect(screen.getByText('PERDAS · mês')).toBeInTheDocument();
  });

  it('barra de meta segue presente como secundária', () => {
    renderHero();
    expect(screen.getAllByTestId('tv-meta-bar').length).toBeGreaterThan(0);
    expect(screen.getByText(/71% da meta/)).toBeInTheDocument();
  });
});

describe('TvHero v3 — filtro global Hoje/Semana/Mês', () => {
  it('dispara onPeriodChange ao clicar em outro período', () => {
    const { onPeriodChange } = renderHero();
    fireEvent.click(screen.getByRole('button', { name: 'Semana' }));
    expect(onPeriodChange).toHaveBeenCalledWith('week');
    fireEvent.click(screen.getByRole('button', { name: 'Mês' }));
    expect(onPeriodChange).toHaveBeenCalledWith('month');
  });

  it('marca o período ativo com aria-pressed', () => {
    renderHero({ period: 'week' });
    expect(screen.getByRole('button', { name: 'Semana' })).toHaveAttribute(
      'aria-pressed',
      'true',
    );
    expect(screen.getByRole('button', { name: 'Hoje' })).toHaveAttribute(
      'aria-pressed',
      'false',
    );
  });
});

describe('TvHero v4 — navegação no histórico (R2)', () => {
  it('◀ navega pro período anterior; ▶ desabilitada em offset 0', () => {
    const { onOffsetChange } = renderHero();
    fireEvent.click(screen.getByRole('button', { name: 'Período anterior' }));
    expect(onOffsetChange).toHaveBeenCalledWith(-1);
    expect(screen.getByRole('button', { name: 'Período seguinte' })).toBeDisabled();
  });

  it('offset 0: indicador live visível, sem chip de range', () => {
    renderHero();
    expect(screen.getByText(/atualizado/)).toBeInTheDocument();
    expect(screen.queryByTestId('tv-range-chip')).not.toBeInTheDocument();
  });

  it('offset < 0: chip do range + "Ao vivo" voltando a 0', () => {
    const { onOffsetChange } = renderHero({ offset: -1 });
    expect(screen.getByTestId('tv-range-chip')).toHaveTextContent('qua. 03/06');
    expect(screen.queryByText(/atualizado/)).not.toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: /ao vivo/i }));
    expect(onOffsetChange).toHaveBeenCalledWith(0);
    // ▶ habilitada no passado
    expect(
      screen.getByRole('button', { name: 'Período seguinte' }),
    ).not.toBeDisabled();
  });
});

describe('TvHero v4 — strip do mês (R3+R4)', () => {
  it('mostra MTD, % da meta mensal, meta da semana e projeção', () => {
    renderHero({ monthProgress });
    const strip = screen.getByTestId('tv-hero-month-strip');
    expect(strip).toBeInTheDocument();
    expect(screen.getByTestId('tv-hero-mtd')).toHaveTextContent('R$ 150k');
    expect(screen.getByTestId('tv-hero-month-goal')).toHaveTextContent(
      '38% de R$ 400k',
    );
    expect(screen.getByTestId('tv-hero-week-goal')).toHaveTextContent('R$ 45k');
    expect(screen.getByTestId('tv-hero-week-goal')).toHaveTextContent('/ R$ 90k');
    expect(screen.getByTestId('tv-hero-week-goal')).toHaveTextContent(
      '50% da semana',
    );
    expect(screen.getByTestId('tv-hero-projection')).toHaveTextContent('R$ 380k');
  });

  it('oculta a barra mensal quando não há meta cadastrada', () => {
    renderHero({
      monthProgress: { ...monthProgress, metaMensal: null, pctMeta: null, currentWeek: null },
    });
    expect(screen.getByTestId('tv-hero-mtd')).toHaveTextContent('R$ 150k');
    expect(screen.queryByTestId('tv-hero-month-goal')).not.toBeInTheDocument();
    expect(screen.queryByTestId('tv-hero-week-goal')).not.toBeInTheDocument();
  });

  it('sem monthProgress (carregando) não renderiza a strip', () => {
    renderHero();
    expect(screen.queryByTestId('tv-hero-month-strip')).not.toBeInTheDocument();
  });
});

describe('TvHero v4 — botão Relatório (R6)', () => {
  it('dispara onReportClick', () => {
    const { onReportClick } = renderHero();
    fireEvent.click(screen.getByRole('button', { name: /relatório/i }));
    expect(onReportClick).toHaveBeenCalledTimes(1);
  });
});

